from functools import wraps
from taf.ue.fastmile.exceptions import NoIpError


def add_interface_trace(interface):

    @wraps(interface)
    def wrappedinterface(self, *args, **kwargs):
        self.logger.debug("executing {} with args={} kwargs={}".format(interface.__name__, args, kwargs))
        response = interface(self, *args, **kwargs)
        self.logger.debug("{} response={}".format(interface.__name__, response))
        return response

    return wrappedinterface


def get_ue_ip(ue_pc, ue_id, logger):
    """

    :param ue_pc:   Rpc object responsible for HTTP/HTTPS request
    :param ue_id:   id of ue, e.g. 192.168.1.1
    :param logger:
    :return:
    """
    ue_ips_dict = ue_pc.get_ue_info(ue_id=ue_id, ue_attributes=['ips'])['ips']
    logger.debug("Got FastMile ips: {}".format(ue_ips_dict))
    if len(ue_ips_dict) == 0:
        raise NoIpError("FastMile didn't get any IP address.")
    for ue_if_name, ue_ips in ue_ips_dict.items():
        return ue_ips[0]
